def linear_bptt(x, w, h0):
    h, d = h0, 0.0
    for xt in x:
        h = w * h + xt
        d = h + w * d
    return h, d

def linear_bptt(x, w, h0):
    h, d = h0, 0.0
    for xt in x:
        d = d + h
        h = w * h + xt
    return h, d
